"""Source facts for the visual atlas. Keep prose with the relevant graph node."""
GRAPHS = []

def graph(key, title, intro, source, outcome):
    g = dict(id=key, title=title, intro=intro, source=source, outcome=outcome, nodes=[], edges=[])
    GRAPHS.append(g)
    return g

def node(g, key, title, sub, detail, kind='step', artifact='', source=None):
    g['nodes'].append(dict(id=key, title=title, sub=sub, detail=detail, kind=kind,
                           artifact=artifact, source=source or g['source']))

def edges(g, *items):
    for item in items:
        parts = item.split('|')
        a, b = parts[0].split('>')
        g['edges'].append(dict(a=a, b=b, label=parts[1] if len(parts)>1 else '',
                               kind=parts[2] if len(parts)>2 else 'normal'))

